package com.glypdl.android.data.model

/**
 * Type of subtitle track: either manually uploaded by the creator, or automatically generated.
 */
enum class SubtitleType {
    MANUAL,
    AUTOMATIC;

    val displayName: String
        get() = when (this) {
            MANUAL -> "Manual"
            AUTOMATIC -> "Auto-generated"
        }
}

/**
 * Preferred subtitle file format conversion when downloading.
 */
enum class SubtitleFormatPreference(val format: String, val label: String) {
    BEST("best", "Original (Best)"),
    SRT("srt", "SubRip (.srt)"),
    VTT("vtt", "WebVTT (.vtt)"),
    ASS("ass", "Advanced SubStation (.ass)"),
    SSA("ssa", "SubStation Alpha (.ssa)"),
    LRC("lrc", "Lyrics (.lrc)");

    val displayName: String get() = label

    companion object {
        fun fromString(value: String?): SubtitleFormatPreference {
            return entries.firstOrNull { it.format.equals(value, ignoreCase = true) } ?: BEST
        }

        fun fromFormat(value: String?): SubtitleFormatPreference {
            val clean = value?.trim()?.lowercase()?.removePrefix(".")
            return entries.firstOrNull { it.format.equals(clean, ignoreCase = true) } ?: BEST
        }
    }
}

/**
 * Download mode controlling whether subtitles, media, or both are retrieved.
 */
enum class SubtitleDownloadMode(val label: String, val description: String) {
    MEDIA_ONLY("Media Only", "Download video/audio without subtitles"),
    MEDIA_WITH_SUBS("Media + Subtitles", "Download media and separate subtitle files"),
    EMBED_SUBS("Embed in Video", "Embed subtitle tracks directly into video container (MKV/MP4)"),
    SUBS_ONLY("Subtitles Only", "Download only subtitle files without downloading video")
}

/**
 * Represents a single subtitle or caption track extracted from yt-dlp metadata.
 *
 * @property languageCode ISO language code (e.g., "en", "es", "ta", "zh-Hans").
 * @property languageName Human-readable language name (e.g., "English", "Spanish").
 * @property type Whether track is manually authored ([SubtitleType.MANUAL]) or generated ([SubtitleType.AUTOMATIC]).
 * @property formats Available file extensions for this track (e.g., ["vtt", "srt", "srv3"]).
 * @property url Direct download URL if provided by the extractor.
 * @property isDefault True if this track is flagged as the default subtitle track.
 */
data class SubtitleTrack(
    val languageCode: String,
    val languageName: String,
    val type: SubtitleType,
    val formats: List<String> = emptyList(),
    val url: String? = null,
    val isDefault: Boolean = false
) {
    val isAutoGenerated: Boolean get() = type == SubtitleType.AUTOMATIC

    val displayLabel: String
        get() = if (languageName.isNotBlank() && languageName != languageCode) {
            "$languageName ($languageCode)"
        } else {
            languageCode
        }
}

/**
 * User-selected subtitle configuration passed to yt-dlp during download execution.
 *
 * @property mode Download mode ([SubtitleDownloadMode]).
 * @property selectedLanguages Set of language codes to download (e.g. ["en", "es"]).
 * @property downloadAllLanguages When true, downloads all available subtitle tracks.
 * @property preferredFormat Preferred subtitle conversion format ([SubtitleFormatPreference]).
 * @property includeManual When true, includes manual subtitles.
 * @property includeAutoGenerated When true, includes automatic captions.
 * @property embedInVideo When true, embeds subtitles into the video file via FFmpeg.
 */
data class SubtitleDownloadOptions(
    val mode: SubtitleDownloadMode = SubtitleDownloadMode.MEDIA_ONLY,
    val selectedLanguages: Set<String> = emptySet(),
    val downloadAllLanguages: Boolean = false,
    val preferredFormat: SubtitleFormatPreference = SubtitleFormatPreference.BEST,
    val includeManual: Boolean = true,
    val includeAutoGenerated: Boolean = false,
    val embedInVideo: Boolean = false
) {
    val isEnabled: Boolean
        get() = mode != SubtitleDownloadMode.MEDIA_ONLY

    val isSubtitlesOnly: Boolean
        get() = mode == SubtitleDownloadMode.SUBS_ONLY

    val shouldEmbed: Boolean
        get() = mode == SubtitleDownloadMode.EMBED_SUBS || embedInVideo

    val hasSelections: Boolean
        get() = downloadAllLanguages || selectedLanguages.isNotEmpty()
}

/**
 * Result representing a successfully downloaded and exported subtitle file.
 *
 * @property id Unique identifier.
 * @property downloadId Associated media download UUID if downloaded alongside media.
 * @property mediaTitle Title of the source video/audio.
 * @property mediaUrl Webpage URL of the source media.
 * @property languageCode Subtitle language code (e.g. "en").
 * @property languageName Subtitle language name (e.g. "English").
 * @property format File extension (e.g. "srt", "vtt").
 * @property isAutoGenerated True if from auto-generated captions.
 * @property localPath Local filesystem path if accessible.
 * @property contentUri Android content URI string.
 * @property fileSize File size in bytes.
 * @property createdAt Timestamp in milliseconds.
 */
data class SubtitleFile(
    val id: Long = 0,
    val downloadId: String? = null,
    val mediaTitle: String,
    val mediaUrl: String? = null,
    val languageCode: String,
    val languageName: String,
    val format: String,
    val isAutoGenerated: Boolean = false,
    val filePath: String? = null,
    val fileName: String = "",
    val contentUri: String,
    val fileSize: Long,
    val createdAt: Long = System.currentTimeMillis(),
    val isEmbedded: Boolean = false
) {
    val localPath: String? get() = filePath
}

/**
 * Combined execution result from yt-dlp including media path and any downloaded subtitle files.
 */
data class SubtitleDownloadResult(
    val mediaFilePath: String? = null,
    val subtitleFiles: List<SubtitleFile> = emptyList(),
    val error: String? = null
)
